<?php declare(strict_types=1); namespace Tests\Integration\QuestionBank; use App\Infrastructure\Persistence\Doctrine\DoctrineEntityManagerFactory; use App\Infrastructure\Persistence\Doctrine\QuestionBank\DoctrineQuestionImportAnalysisRepository; use App\Domain\QuestionBank\Entity\QuestionImportAnalysis; use App\Domain\QuestionBank\ValueObject\{QuestionImportMetadata,QuestionImportTokenUsage,QuestionImportFinding,QuestionImportImageAnchor}; use App\Domain\QuestionBank\Enum\{QuestionImportUsageAvailability,QuestionImportStructureType,QuestionImportAnswerKeyAssessment,QuestionImportImageAssessment,QuestionImportFindingCode,QuestionImportFindingSeverity,QuestionImportImageTarget,QuestionImportImageAnchorStatus}; use PHPUnit\Framework\TestCase; final class DoctrineQuestionImportAnalysisRepositoryTest extends TestCase { public function testPersistsAndReadsImmutableAnalysis():void{$em=DoctrineEntityManagerFactory::create();$db=$em->getConnection();$job='b2000000-0000-4000-8000-'.substr(bin2hex(random_bytes(6)),0,12);$id='b1000000-0000-4000-8000-'.substr(bin2hex(random_bytes(6)),0,12);$db->beginTransaction();try{$db->executeStatement('SET FOREIGN_KEY_CHECKS=0');$db->insert('question_pdf_import_jobs',['id'=>$job,'created_by'=>$id,'document_path'=>'/tmp/a','document_sha256'=>str_repeat('a',64),'document_original_name'=>'a.pdf','status'=>'PENDING','progress'=>0,'page_count'=>0,'candidate_pages'=>0,'processed_chunks'=>0,'retry_count'=>0,'extracted_questions'=>0,'classified_questions'=>0,'created_questions'=>0,'duplicate_questions'=>0,'failed_questions'=>0,'created_taxonomy_subjects'=>0,'created_at'=>(new \DateTimeImmutable())->format('Y-m-d H:i:s')]);$a=new QuestionImportAnalysis($id,$job,null,str_repeat('b',64),'v1','v1','codex',null,[1],new QuestionImportMetadata(null,null,null,null,[]),QuestionImportStructureType::MULTIPLE_CHOICE,QuestionImportAnswerKeyAssessment::CONFLICT,QuestionImportImageAssessment::DISCREPANCY,new QuestionImportTokenUsage(QuestionImportUsageAvailability::AVAILABLE,1,1,2,null),1,[new QuestionImportFinding('b3000000-0000-4000-8000-'.substr(bin2hex(random_bytes(6)),0,12),QuestionImportFindingCode::ANSWER_KEY_CONFLICT,QuestionImportFindingSeverity::WARNING,null,'Revisão recomendada.',[1])],[new QuestionImportImageAnchor('b4000000-0000-4000-8000-'.substr(bin2hex(random_bytes(6)),0,12),QuestionImportImageTarget::STATEMENT,null,1,0,QuestionImportImageAnchorStatus::AMBIGUOUS)],new \DateTimeImmutable());$r=new DoctrineQuestionImportAnalysisRepository($em);$r->save($a);$em->flush();$em->clear();$x=$r->listForJob($job);self::assertCount(1,$x);self::assertSame(QuestionImportAnswerKeyAssessment::CONFLICT,$x[0]->answerKeyAssessment);self::assertSame(QuestionImportImageAnchorStatus::AMBIGUOUS,$x[0]->imageAnchors[0]->status);$this->expectException(\DomainException::class);$r->save($a);}finally{$db->executeStatement('SET FOREIGN_KEY_CHECKS=1');$db->rollBack();$em->clear();}} }
